Lemma ret_at : CL.is_ret_at RSEGS PSC.RETPC.
Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "U37;Y5;00;A1;o2;#0;A1;i1;#1;A1;o2;Y2;1;A1;i1;#3;A1;o2;Y3;4;A1;i1;#5;A1;i6;#2;Y6;00;A2;k7;k8;A2;k9;A1;o2;#8;k10;A2;i15;i16;i17;A1;i6;#10;Y2;0;A1;o21;#12;A2;o11;#10;A4;o19;i16;i17;A3;o20;r3;r2;r1;#13;A1;o21;o24;A3;i5;i17;A2;k22;#5;r1;o23;A2;i4;A3;i5;i17;A2;k22;#3;r2;#15;#16;A2;i4;A3;i5;i17;A2;k22;#3;r3;o23;#17;A1;o21;Y15;0067;A3;o25;#1;#19;A2;k26;#1;#19;A2;o11;#2;#20;A3;i5;#7;#9;#21;A3;i5;i12;A1;k13;#20;o14;A1;k18;#20;A1;k27;#20;A3;i5;i17;A2;k22;#3;#25;o23;A1;k28;#20;A3;i5;i17;A2;k22;#3;#27;#15;A1;k29;#20;A2;o11;#10;A4;o19;i16;i17;A3;o20;#25;#27;#29;#13;A3;i5;#11;#24;#30;A3;i5;i17;A2;k22;#5;#29;o23;A2;i4;#28;#32;A2;i4;#26;#33;A2;i4;#31;#34;A2;o31;i17;o23;cdA4;o0;#2;Lw;R#2;A2;i3;#4;Lrd;R#4;A2;i3;#4;Lrs1;R#4;A2;i3;#6;Limm;R#6;A2;i4;A3;i5;#7;#9;A2;o11;#2;r4;A2;i4;A3;i5;i12;A1;k13;r4;o14;A2;i4;A3;i5;#11;A1;k18;r4;#14;#18;#20;A4;o0;#4;Lrd;R#4;A2;i3;#4;Lrs1;R#4;A2;i3;#6;Limm;R#6;A2;i4;#22;A2;i4;#23;A2;i4;A3;i5;#11;#24;#14;#18;#25;A4;o0;#4;Lrs1;R#4;A2;i3;#6;Limm;R#6;A2;i4;#22;A2;i4;#23;A2;i4;A3;i5;#11;#24;A2;o11;#10;A4;o19;i16;i17;A3;o20;#25;r2;r1;#13;A2;i4;#26;#17;#27;A4;o0;#6;Limm;R#6;A2;i4;#22;A2;i4;#23;A2;i4;A3;i5;#11;#24;A2;o11;#10;A4;o19;i16;i17;A3;o20;#25;#27;r1;#13;A2;i4;#26;A2;i4;#28;#16;#29;A4;o30;#22;A2;i4;#23;#35;cvA2;o31;#7;#21;#22;A4;o30;#23;#35;A2;o31;i12;o14;A4;o30;#31;#34;A2;o31;#11;#30;A4;o30;#26;#33;#36;A4;o30;#28;#32;A2;o31;i17;#15;#36;A2;k32;k8;k10;").
Qed.

Definition box (X : Prop) : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 1 "S0;LX;Rpr1;").
Definition boxed {X : Prop} (x : X) : box X := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S0;LX;RpLx;Rr1;r1;").

Lemma win_piece_arith : forall q n p wlen e cur len B,
  0 <= q < 2 ^ 64 -> 0 <= n <= 16384 ->
  4096 <= p -> 0 <= wlen -> p + wlen <= 2 ^ 47 -> p + wlen = e -> 0 <= len -> len + (e - cur) <= B -> B < 2 ^ 26 -> p <= cur <= p + 16384 -> 1 <= e - cur <= 16384 ->
  0 <= (q - p) mod 2 ^ 64 <= 16384 -> 0 <= (e - (q + n) mod 2 ^ 64) mod 2 ^ 64 <= 16384 -> 0 <= (cur - q) mod 2 ^ 64 <= 16384 ->
